motor LeftMotorB = motor(PORT2, ratio18_1, false);
motor RightMotorA = motor(PORT3, ratio18_1, true);
motor RightMotorB = motor(PORT4, ratio18_1, true);

motor_group LeftDrive = motor_group(LeftMotorA, LeftMotorB);
motor_group RightDrive = motor_group(RightMotorA, RightMotorB);

// Sensors — calibrate in autonomous(), NOT in pre_auton()
inertial Inertial1 = inertial(PORT5);

// Mechanisms — example arm and intake motors
motor ArmMotor = motor(PORT6, ratio36_1, false);
motor IntakeMotor = motor(PORT7, ratio18_1, false);

// <R9> Competition object registers autonomous + driver callbacks
competition Competition;

// ── Pre-Autonomous ──
// Runs before the Match; robot is OFF the Field
void pre_auton(void) {
    vexcodeInit();  // Initialize all VEXcode-configured devices

    // Set brake modes for predictable behavior
    LeftDrive.setStopping(brake);
    RightDrive.setStopping(brake);
    ArmMotor.setStopping(hold);     // Hold position when not actively moving
    IntakeMotor.setStopping(coast);

    // NOTE: Do NOT calibrate sensors here.
    // Robot gets moved onto Field after pre_auton(), causing drift.
    // Calibrate / reset heading at the start of autonomous() instead.
}

// ── Autonomous Period ──
// <GG12> Autonomous = "no humans" — 15 seconds
// <SG7> Do NOT cross the Autonomous Line
// <SC7> Autonomous Bonus evaluated immediately after Autonomous ends
// <SC8> AWP: 7+ Pins, 3+ Goals with 2+ Pins each, no Field Perimeter contact
void autonomous(void) {
    // Reset heading FIRST — robot is now on the Field
    Inertial1.resetHeading();

    // TODO: Write your autonomous strategy below
