    // 2. Place Preload Pin on Goal
    // 3. Park in Midfield for bonus points

    // LeftDrive.spinFor(forward, 500, degrees);  // Move forward
    // RightDrive.spinFor(forward, 500, degrees);
    // wait(200, msec);
    // LeftDrive.stop(brake);
    // RightDrive.stop(brake);
}

// ── Driver Controlled Period ──
// <GG11> Only Drive Team Members in Alliance Station
// <GG12> Driver interacts via V5 Controller
void usercontrol(void) {
    while (true) {
        // Arcade Drive — left stick forward/back, right stick left/right
        double forwardAxis = Controller1.Axis3.position();  // [-100, 100]
        double turnAxis = Controller1.Axis1.position();     // [-100, 100]

        LeftDrive.spin(forward, forwardAxis + turnAxis, percent);
        RightDrive.spin(forward, forwardAxis - turnAxis, percent);

        // Arm control — L1 up, L2 down, hold when idle
        if (Controller1.ButtonL1.pressing()) {
            ArmMotor.spin(forward, 60, percent);
        } else if (Controller1.ButtonL2.pressing()) {
            ArmMotor.spin(reverse, 60, percent);
        } else {
            ArmMotor.stop(hold);  // <R27> Hold prevents arm from dropping
        }

        // Intake control — R1 in, R2 out
        if (Controller1.ButtonR1.pressing()) {
            IntakeMotor.spin(forward, 100, percent);
        } else if (Controller1.ButtonR2.pressing()) {
            IntakeMotor.spin(reverse, 100, percent);
        } else {
            IntakeMotor.stop(coast);
        }

        wait(20, msec);  // Prevent CPU overload
    }
}

// ── Main ──
int main() {
    Competition.autonomous(autonomous);
    Competition.drivercontrol(usercontrol);

    pre_auton();

    while (true) {
        wait(100, msec);  // Keep main loop alive
    }
}

