// ============================================================
// VEX V5 Autonomous Routine Template — OVERRIDE 2026-2027
// <SC7> Autonomous Bonus (12 pts)
// <SC8> Autonomous Win Point criteria
// <SG7> Do NOT cross the Autonomous Line
// ============================================================

// ── Constants ──
// TODO: Measure your robot's actual wheel diameter (inches)
#define WHEEL_DIAMETER 3.25
#define PI 3.14159265

// ── Helper: Gyro-Assisted Drive Straight ──
// Uses proportional correction to keep robot on heading
void drive_straight(double inches, double speed_pct) {
    // Convert inches to motor degrees
    double target_deg = (inches / (PI * WHEEL_DIAMETER)) * 360.0;

    LeftDrive.setPosition(0, degrees);
    RightDrive.setPosition(0, degrees);

    double start_heading = Inertial1.heading(degrees);
    double kP = 0.6;  // Proportional gain — tune for your robot

    while (fabs(LeftDrive.position(degrees)) < target_deg) {
        double current_heading = Inertial1.heading(degrees);
        double error = current_heading - start_heading;

        // Normalize error to [-180, 180]
        while (error > 180.0) error -= 360.0;
        while (error < -180.0) error += 360.0;

        double correction = error * kP;

        LeftDrive.spin(forward, speed_pct + correction, percent);
        RightDrive.spin(forward, speed_pct - correction, percent);
        wait(20, msec);
    }

    LeftDrive.stop(brake);
    RightDrive.stop(brake);
}

// ── Helper: Proportional Turn to Heading ──
void turn_to(double target_heading) {
    double kP = 0.5;  // Tune for your robot

    while (true) {
        double current = Inertial1.heading(degrees);
        double error = target_heading - current;

        // Normalize error to [-180, 180]
        while (error > 180.0) error -= 360.0;
        while (error < -180.0) error += 360.0;

        if (fabs(error) < 1.5) break;  // Tolerance: 1.5 degrees

        double power = error * kP;
        // Clamp power to [-100, 100]
        if (power > 100) power = 100;
        if (power < -100) power = -100;

        LeftDrive.spin(forward, power, percent);
        RightDrive.spin(reverse, power, percent);
        wait(20, msec);
    }

    LeftDrive.stop(brake);
    RightDrive.stop(brake);
}

// ── Main Autonomous Sequence ──
void autonomous(void) {
    // Calibrate heading FIRST — robot is now on the Field
    Inertial1.resetHeading();

    // Step 1: Drive forward to scoring position
    drive_straight(24.0, 60);  // 24 inches at 60% speed
    wait(200, msec);

    // Step 2: Turn to face the Goal
    turn_to(90.0);  // Turn right 90 degrees
    wait(200, msec);

    // Step 3: Place Preload Pin (run intake in reverse)
    IntakeMotor.spinFor(reverse, 300, degrees);
    wait(100, msec);
    IntakeMotor.stop(brake);

    // Step 4: Park in the Midfield
    // <SC6> Robot must be contacting the Midfield at end of Match
    turn_to(0.0);
    drive_straight(18.0, 50);  // 18 inches at 50% speed

    // Ensure all motors stop before Autonomous ends
    LeftDrive.stop(brake);
    RightDrive.stop(brake);
}

