void usercontrol(void) {
    // Configure brake modes for driver control
    LeftDrive.setStopping(brake);
    RightDrive.setStopping(brake);
    ArmMotor.setStopping(hold);     // <R27> Arm holds position when idle
    IntakeMotor.setStopping(coast);

    while (true) {
        // ── Arcade Drive ──
        // Axis3 = left stick Y-axis (forward/backward)
        // Axis1 = right stick X-axis (turn)
