#include "vex.h"
using namespace vex;

// ── Pattern 1: Individual Drive Motors ──
// Two motors per side, one reversed for mirrored output
motor LeftMotorA = motor(PORT1, ratio18_1, false);   // Normal direction
motor LeftMotorB = motor(PORT2, ratio18_1, false);   // Same as A
motor RightMotorA = motor(PORT3, ratio18_1, true);   // REVERSED (mirrored)
motor RightMotorB = motor(PORT4, ratio18_1, true);   // REVERSED (mirrored)

// ── Pattern 2: Gear Ratio Selection ──
// ratio6_1  → Turbo  (600 RPM) — fast, for flywheels / intakes
// ratio18_1 → Speed  (200 RPM) — balanced, for drive
// ratio36_1 → Torque (100 RPM) — powerful, for arms / lifts
// motor ExampleTurbo = motor(PORT5, ratio6_1, false);
motor ArmMotor = motor(PORT6, ratio36_1, false);      // High torque for lifting
motor IntakeMotor = motor(PORT7, ratio18_1, false);   // Speed for ball intake

// ── Pattern 3: Motor Groups ──
// Group same-side motors so they act as one logical unit
motor_group LeftDrive = motor_group(LeftMotorA, LeftMotorB);
motor_group RightDrive = motor_group(RightMotorA, RightMotorB);

// ── Pattern 4: Single Motor in Group ──
// If you only have one motor per side, still use motor_group for consistency
// motor_group LeftDrive = motor_group(LeftMotorA);
// motor_group RightDrive = motor_group(RightMotorA);

// ── Brake Mode Best Practices ──
void pre_auton(void) {
    vexcodeInit();

    // brake  = Rapid deceleration, motors resist movement (drive base)
    LeftDrive.setStopping(brake);
    RightDrive.setStopping(brake);

    // hold   = Active position lock, prevents back-driving (arms, lifts)
    ArmMotor.setStopping(hold);

    // coast  = Free spin, no resistance (rollers, intakes)
    IntakeMotor.setStopping(coast);
}

