// ============================================================
// VEX V5 Sensor Setup Patterns — OVERRIDE 2026-2027
// <R28> No modifications to electronic/pneumatic components
// ============================================================

#include "vex.h"
using namespace vex;

// ── 1. Inertial Sensor (IMU) ──
// Purpose: Heading (yaw), pitch, roll — critical for autonomous
// Port: Smart Port (any)
inertial Inertial1 = inertial(PORT5);

void init_inertial() {
    // Calibrate (takes ~2 seconds) — do ONCE, e.g., at program start
    Inertial1.calibrate();
    while (Inertial1.isCalibrating()) {
        wait(50, msec);
    }
    // Then in autonomous(), call Inertial1.resetHeading() as first line
}

void use_inertial() {
    double heading = Inertial1.heading(degrees);     // 0–360
    double rotation = Inertial1.rotation(degrees);     // Accumulated (can exceed 360)
    double pitch = Inertial1.pitch(degrees);
    double roll = Inertial1.roll(degrees);
    bool is_still = Inertial1.isCalibrating() == false;
}

// ── 2. Vision Sensor ──
// Purpose: Detect colored objects (Pins, Goals) by signature
// Port: Smart Port (any)
vision Vision1 = vision(PORT6);

void init_vision() {
    // Configure signatures in VEXcode Device Manager (1–7)
    // Each signature: color range, brightness, etc.
    // Example: Signature 1 = Red Pin, Signature 2 = Blue Pin
}

void use_vision() {
    int objCount = Vision1.objectCount();
    if (objCount > 0) {
        vision::object obj = Vision1.largestObject;
        int sigId = obj.id;          // Signature 1–7
        int centerX = obj.centerX;   // Horizontal pixel position
        int centerY = obj.centerY;   // Vertical pixel position
        int width = obj.width;
        int height = obj.height;
    }
    // Camera brightness
    Vision1.setBrightness(50);  // 0–100
}

// ── 3. Rotation Sensor ──
// Purpose: Precise shaft position tracking (3600 ticks/rev)
// Port: Smart Port (any)
rotation Rotation1 = rotation(PORT7);

void use_rotation() {
    double angle = Rotation1.position(degrees);
    double rpm = Rotation1.velocity(rpm);
    Rotation1.setPosition(0, degrees);  // Reset
    // Unlike motor encoder, this tracks external shaft rotation
}

// ── 4. GPS Sensor ──
// Purpose: Absolute field position (requires Field Code strips)
// Port: Smart Port (any)
gps GPS1 = gps(PORT8);

void use_gps() {
    double x = GPS1.xPosition(mm);      // Field X coordinate
    double y = GPS1.yPosition(mm);      // Field Y coordinate
    double heading = GPS1.heading();    // Absolute heading
    double quality = GPS1.quality();    // Signal confidence (0–100)
    // <R28> Do not modify GPS sensor housing
}

// ── 5. Distance Sensor ──
// Purpose: Object detection (proximity) + approximate distance
// Port: Smart Port (any)
distance Distance1 = distance(PORT9);

void use_distance() {
    double dist_mm = Distance1.objectDistance(mm);
    double dist_in = Distance1.objectDistance(inches);
    bool detected = (dist_mm < 200);  // Object within 200mm
    // Approximate size/confidence of detection
    double relSize = Distance1.objectSize();
}

// ── 6. Optical Sensor ──
// Purpose: Color detection (hue), proximity, ambient light
// Port: Smart Port (any)
optical Optical1 = optical(PORT10);

void use_optical() {
    double hue = Optical1.hue();          // 0–360 degrees
    bool is_red = (hue < 20 || hue > 340);
    bool is_blue = (hue > 180 && hue < 260);
    bool is_near = Optical1.isNearObject();
    double brightness = Optical1.brightness();  // 0–100
    // Set LED for active illumination
    Optical1.setLight(ledState::on);
    Optical1.setLightPower(50);  // percent
}

